def _check_structure(self) -> Self:
    """Collect EVERY structural failure into one error, never the first."""
    failures: list[str] = []

    if self.run_event_states:
        try:
            self.require_run_event_table()
        except RunEventTableError as exc:
            failures.extend(exc.failures)

    try:
        self.resolve_organize_mandates()
    except ValueError as exc:
        failures.append(str(exc))

    if self.organize_scopes:
        if not self.organize_mandates:
            failures.append("organize_scopes requires configured organize_mandates")
        refs = [binding.scope for binding in self.organize_scopes]
        if len(refs) != len(set(refs)):
            failures.append(
                "organize_scopes repeats or ambiguously binds one scope"
            )
        for binding in self.organize_scopes:
            if sum(repo.url == binding.repo_url for repo in self.repos) != 1:
                failures.append(
                    "each organize scope requires exactly one matching "
                    "declared repository"
                )

    if self.audit_scopes:
        audit_refs = [binding.scope for binding in self.audit_scopes]
        if len(audit_refs) != len(set(audit_refs)):
            failures.append("audit_scopes repeats or ambiguously binds one scope")
        for audit_binding in self.audit_scopes:
            if sum(repo.url == audit_binding.repo_url for repo in self.repos) != 1:
                failures.append(
                    "each audit scope requires exactly one matching "
                    "declared repository"
                )

    if self.principals:
        approvers = [
            p for p in self.principals if PrincipalRole.APPROVER in p.roles
        ]
        if len(approvers) != 1:
            failures.append(
                f"exactly one APPROVER principal is required, "
                f"found {len(approvers)}",
            )
        assignees = [
            p for p in self.principals if PrincipalRole.ASSIGNEE in p.roles
        ]
        if len(assignees) > 1:
            failures.append(
                f"at most one ASSIGNEE principal may be declared, "
                f"found {len(assignees)}",
            )
    failures.extend(
        f"principals[{index}] must carry the PRINCIPAL role"
        for index, principal in enumerate(self.principals)
        if PrincipalRole.PRINCIPAL not in principal.roles
    )

    # Two keys naming one team is not a synonym, it is an ambiguity: the
    # adapter resolves an issue's team back onto the key a scan was
    # scoped by, and with two candidates that answer is a coin toss.
    names = [entry.name for entry in self.teams.values()]
    failures.extend(
        f"teams[{key!r}].name {entry.name!r} is not unique"
        for key, entry in self.teams.items()
        if names.count(entry.name) > 1
    )

    # The repository binding: one naming a repository the config does
    # not declare routes issues nowhere and is refused.  A team
    # carrying NO binding is legal in both shapes — with one declared
    # repository the binding is implicit and total, and with several
    # the team's issues route per issue by the repository the
    # fire-prep pass records on each staged one (KOD-169).
    declared_repos = {repo.url for repo in self.repos}
    failures.extend(
        f"teams[{key!r}].repository {entry.repository!r} names no declared "
        f"repository"
        for key, entry in self.teams.items()
        if entry.repository is not None and entry.repository not in declared_repos
    )

    if self.queue_states:
        for member in QueueState:
            if member.value not in self.queue_states:
                failures.append(
                    f"queue_states is missing required key {member.value!r}"
                )

    if self.scope_labels:
        for scope_label in ScopeLabel:
            if scope_label.value not in self.scope_labels:
                failures.append(
                    f"scope_labels is missing required key {scope_label.value!r}"
                )

    if self.workflow_states:
        for stage in LifecycleStage:
            if stage not in self.workflow_states:
                failures.append(
                    f"workflow_states is missing required stage {stage.value!r}",
                )

    label_names = list(self.issue_labels.values())
    failures.extend(
        f"issue_labels[{name!r}] must name a nonempty tracker label"
        for name, label in self.issue_labels.items()
        if not name.strip() or not label.strip()
    )
    failures.extend(
        f"issue_labels[{name!r}] {label!r} is not unique"
        for name, label in self.issue_labels.items()
        if label_names.count(label) > 1
    )

    prefixes = list(self.marker_prefixes.values())
    failures.extend(
        f"marker_prefixes[{purpose!r}] must name one nonempty marker token"
        for purpose, prefix in self.marker_prefixes.items()
        if not purpose
        or not prefix
        or any(character.isspace() or character in '<>[]:"' for character in prefix)
    )
    failures.extend(
        f"marker_prefixes[{purpose!r}] {prefix!r} is not unique"
        for purpose, prefix in self.marker_prefixes.items()
        if prefixes.count(prefix) > 1
    )

    if self.documents and CHECKPOINT_DOCUMENT_KEY not in self.documents:
        failures.append(
            f"documents is missing the stable checkpoint key "
            f"{CHECKPOINT_DOCUMENT_KEY!r}",
        )

    # A container names the declared team the create arm files the
    # document under, so a key outside ``teams`` routes creation
    # nowhere and is refused at load rather than at the vendor.
    failures.extend(
        f"documents[{key!r}].container {entry.container!r} names no declared team"
        for key, entry in self.documents.items()
        if entry.container is not None and entry.container not in self.teams
    )

    # Record keys ARE the run-kind vocabulary: each declares the one
    # destination its kind reports to, so a free name here would be a
    # log nothing ever writes (KOD-170).  Absence of a kind is legal —
    # a named absence the recorder reports — but an unknown key is not.
    valid_record_keys = {kind.value for kind in RunKind}
    failures.extend(
        f"records[{key!r}] is not a run kind; declare one of "
        f"{sorted(valid_record_keys)}"
        for key in self.records
        if key not in valid_record_keys
    )

    for index, repo in enumerate(self.repos):
        failures.extend(
            f"repos[{index}].checks: {failure}"
            for failure in check_chain_failures(repo.checks)
        )

    known_users = {p.tracker_user for p in self.principals}
    failures.extend(
        f"agent_identities[{index}] {identity!r} collides with a principal"
        for index, identity in enumerate(self.agent_identities)
        if identity in known_users
    )

    handles = [p.handle for p in self.principals]
    failures.extend(
        f"principals[{index}].handle must not be empty"
        for index, handle in enumerate(handles)
        if not handle.strip()
    )
    failures.extend(
        f"principals[{index}].handle {handle!r} is not unique"
        for index, handle in enumerate(handles)
        if handles.count(handle) > 1
    )
    failures.extend(
        f"principals[{index}].handle {handle!r} collides with an agent identity"
        for index, handle in enumerate(handles)
        if handle in set(self.agent_identities)
    )

    if failures:
        raise ValueError("; ".join(failures))
    return self

INSTATABLE_MAPPING_KINDS: frozenset[MappingKind] = frozenset(
    {
        MappingKind.QUEUE_STATE,
        MappingKind.SCOPE_LABEL,
        MappingKind.ISSUE_LABEL,
        MappingKind.DOCUMENT,
    },
)

def configured_mappings(config: OperationConfig) -> tuple[MappingRef, ...]:
    """Every mapping entry boot validation must resolve, in a stable order.

    ``documents`` are absent from this pass and that is deliberate: the
    ensure is what establishes them and it reports the identifier the
    workspace holds, so a resolution pass over the same values would re-ask
    the tool that just answered.  What this pass exists to catch is the
    class no boot can instate — a principal, a team, a lifecycle state.

    ``records`` are EXTERNAL and so belong here, tracker-side ones at
    least: a record destination declares an id it did not assign itself,
    which is exactly the class this pass resolves, and a typo in one used
    to survive boot and fail inside an unattended pass session instead.  A
    tracker-side record IS a document to this backend, so it resolves as
    one.  A record in the KNOWLEDGE system is left alone: no client in this
    process can open that store, so nothing here could ask — their boot
    guard is the grant-coverage check at the composition root.
    """
    refs: list[MappingRef] = [
        MappingRef(
            kind=MappingKind.USER,
            name="+".join(sorted(role.value for role in principal.roles)),
            identifier=principal.tracker_user,
        )
        for principal in config.principals
    ]
    refs.extend(
        MappingRef(
            kind=MappingKind.USER,
            name=identity,
            identifier=identity,
        )
        for identity in config.agent_identities
    )
    refs.extend(
        MappingRef(kind=MappingKind.TEAM, name=team_key, identifier=entry.name)
        for team_key, entry in sorted(config.teams.items())
    )
    refs.extend(
        MappingRef(kind=MappingKind.QUEUE_STATE, name=name, identifier=identifier)
        for name, identifier in sorted(config.queue_states.items())
    )
    refs.extend(
        MappingRef(kind=MappingKind.SCOPE_LABEL, name=name, identifier=identifier)
        for name, identifier in sorted(config.scope_labels.items())
    )
    refs.extend(
        MappingRef(kind=MappingKind.ISSUE_LABEL, name=name, identifier=identifier)
        for name, identifier in sorted(config.issue_labels.items())
    )
    refs.extend(
        MappingRef(
            kind=MappingKind.WORKFLOW_STATE,
            name=stage.value,
            identifier=identifier,
        )
        for stage, identifier in sorted(
            config.workflow_states.items(),
            key=lambda item: item[0].value,
        )
    )
    refs.extend(
        MappingRef(
            kind=MappingKind.DOCUMENT,
            name=entry.name,
            identifier=entry.id,
        )
        for _, entry in sorted(config.records.items())
        if entry.system is DocumentSystem.TRACKER
    )
    return tuple(refs)

def _scope_label_refs(
    config: OperationConfig,
    _containers: tuple[str | None, ...],
) -> tuple[MappingRef, ...]:
    """One workspace ref per scope label, shared across container kinds.

    An initiative and a project have no issue-team namespace. The adapter
    instates the same configured name in each native label namespace;
    creating team copies would make the issue spelling ambiguous.
    """
    return tuple(
        MappingRef(kind=MappingKind.SCOPE_LABEL, name=name, identifier=identifier)
        for name, identifier in sorted(config.scope_labels.items())
    )

OWNED_REF_BUILDERS: dict[
    str,
    Callable[[OperationConfig, tuple[str | None, ...]], tuple[MappingRef, ...]],
] = {
    "documents": _document_refs,
    "queue_states": _queue_state_refs,
    "scope_labels": _scope_label_refs,
    "issue_labels": _issue_label_refs,
}

def _scope_label_members(self, labels: Sequence[str]) -> frozenset[ScopeLabel]:
    return frozenset(
        member
        for member in ScopeLabel
        if self._scope_labels.get(member.value) in labels
    )

async def _read_scope_issue(
    self, issue_key: str
) -> tuple[TrackerIssue, frozenset[ScopeLabel]]:
    payload = await self._call(
        _TOOL_GET_ISSUE, {"id": issue_key, "includeRelations": True}
    )
    wire = self._validate(LinearApprovalIssueWire, payload, _TOOL_GET_ISSUE)
    issue = self._to_issue(wire)
    if not wire.matches_requested(issue_key):
        raise ScopeReadError(
            "scope label identity changed",
            ref=ScopeRef(kind=ScopeKind.ISSUE, key=issue_key),
        )
    return issue, self._scope_label_members(wire.labels)

async def read_scope_labels(self, *, ref: ScopeRef) -> frozenset[ScopeLabel]:
    if ref.kind is ScopeKind.ISSUE:
        _, members = await self._read_scope_issue(ref.key)
        return members
    reader = LinearScopeReader(call=self._call, read_issue=self.read_issue)
    if ref.kind is ScopeKind.MILESTONE:
        await reader.container_metadata(ref=ref)
        return frozenset()
    labels, _ = await reader.labels_parent(ref=ref)
    return self._scope_label_members(tuple(labels))

async def _scope_label_definitions(
    self,
    issue_definitions: _LabelListings,
) -> dict[str, set[str]]:
    """Keep native namespaces apart: one label id cannot stand for all."""
    return {
        tool: (
            issue_definitions.workspace
            if tool == _TOOL_LIST_ISSUE_LABELS
            else {entry.name for entry in await self._label_entries({}, tool=tool)}
        )
        for tool in _SCOPE_LABEL_CREATORS
    }

async def project_milestones(
    self, *, project_key: str
) -> tuple[ScopeContainer, ...]:
    return await LinearScopeReader(
        call=self._call, read_issue=self.read_issue
    ).project_milestones(project_key=project_key)

async def project_milestones(
    self, *, project_key: str
) -> tuple[ScopeContainer, ...]:
    ref = ScopeRef(kind=ScopeKind.PROJECT, key=project_key)
    project = await self._project(project_key)
    if project.id != project_key:
        raise ScopeReadError(
            "project milestone lookup returned another identity", ref=ref
        )
    # This tool explicitly returns all milestones and has no cursor input.
    listed = await self._read(
        LinearScopeMilestonesWire, _TOOL_LIST_MILESTONES, {"project": project.id}
    )
    keys = [item.id for item in listed.milestones]
    if len(set(keys)) != len(keys):
        raise ScopeReadError("project milestones repeat a native identity", ref=ref)
    milestones: list[ScopeContainer] = []
    for key in sorted(keys):
        current = await self._read(
            LinearScopeMetadataWire,
            _TOOL_GET_MILESTONE,
            {"project": project.id, "query": key},
        )
        if current.id != key:
            raise ScopeReadError(
                "milestone detail returned another identity", ref=ref
            )
        milestones.append(
            ScopeContainer(
                ref=ScopeRef(kind=ScopeKind.MILESTONE, key=key),
                name=current.name,
                description=current.description or "",
                url=None,
                parent=ref,
            )
        )
    repeated = await self._read(
        LinearScopeMilestonesWire, _TOOL_LIST_MILESTONES, {"project": project.id}
    )
    if sorted(item.id for item in repeated.milestones) != sorted(keys):
        raise ScopeReadError(
            "project milestone membership changed while reading", ref=ref
        )
    return tuple(milestones)

async def resolve_execution_approval(
    *,
    issue_key: str,
    read_issue: ReadIssueApproval,
    read_container: ReadContainerApproval,
) -> bool:
    """Read issue ancestors, then the addressed issue's container ancestors.

    Container membership remains independent of issue parent edges. A
    parent issue's explicit approval covers its descendants across projects;
    its project label covers that project's actual members. Milestones add
    no label level: their project supplies container approval.
    """
    requested = ScopeRef(kind=ScopeKind.ISSUE, key=issue_key)
    seen: set[ScopeRef] = set()
    key: str | None = issue_key
    project: str | None = None
    while key is not None:
        ref = ScopeRef(kind=ScopeKind.ISSUE, key=key)
        if ref in seen:
            raise ScopeReadError("issue parent cycle", ref=requested)
        seen.add(ref)
        issue, approved = await read_issue(key)
        if issue.issue_key != key:
            raise ScopeReadError("issue approval identity changed", ref=requested)
        if key == issue_key:
            project = issue.project_id
            if issue.milestone_key is not None and project is None:
                raise ScopeReadError(
                    "milestone member has no owning project", ref=requested
                )
            if issue.project is not None and project is None:
                raise ScopeReadError(
                    "project membership has no canonical key", ref=requested
                )
        if approved:
            return True
        key = issue.parent_key

    ancestor = (
        ScopeRef(kind=ScopeKind.PROJECT, key=project) if project is not None else None
    )
    while ancestor is not None:
        if ancestor in seen:
            raise ScopeReadError("container parent cycle", ref=requested)
        seen.add(ancestor)
        approved, parent = await read_container(ancestor)
        if parent is not None and parent.kind is not ScopeKind.INITIATIVE:
            raise ScopeReadError("invalid approval container parent", ref=ancestor)
        if approved:
            return True
        ancestor = parent
    return False

def _check_trunk_base(self) -> Self:
    if self.base_spec is None and not self.base_branch:
        msg = "baseBranch must not be empty when baseSpec is absent"
        raise ValueError(msg)
    return self
